SELECT * FROM (SELECT is_flagged, CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END AS txn_cohort, MAX(amount) AS max_amount FROM transactions WHERE merchant <> 'Lazada' GROUP BY is_flagged, CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END) AS sub WHERE max_amount >= 3500
